css:
/* ==== INTERFACE ====
方向：瑞士国际主义风格（Swiss Style），结合公共交通导视体系的几何清晰性与严谨网格。大比例字号反差、严整坐标对齐轴、直角色块划分与克制规则线，以精准的排印与数据对比服务地铁出行工作坊。
reference style:02-swiss
token --bg：画布主底色（纯净柔和的高阶灰白 #F4F4F2）。
token --text：主正文与主要文字深色 (#121314)。
token --font-sans：通用正文与控件字体栈（NTF-inter 与 NTF-noto-sans-sc）。
token --font-display：展示与标题字体栈（英文 NTF-barlow-condensed 搭配中文 NTF-noto-sans-sc 800字重）。
class .nt-title：普通页题名，字号 44px，行高 1.15，字重 800，非对称左侧强对齐。
class .nt-h2：模块与区块标题，字号 24px，行高 1.25，字重 700。
class .nt-lead：引导语与核心结论，字号 20px，行高 1.45，字重 500。
class .nt-label：小标、图例与技术标签，字号 13px，行高 1.2，等宽/窄体，大写或加粗。
class .nt-metro-badge：地铁线路识别块（直角、色块填充或反白、鲜明路线编号）。
class .nt-card：直角纯净信息看板容器，带精密细边框与强对比标头，绝无模糊杂影。
class .nt-btn：直角无圆角交互按钮，反色悬停与清晰激活态。
variant opening：开篇主视觉，强化英中文特大尺度字级对比与标牌色块（纯红警示色块 #E63926）。
==== /INTERFACE ==== */

/* ---- 字体声明 ---- */
@font-face {
  font-family: "NTF-noto-sans-sc";
  src: url("fonts/library/noto-sans-sc/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-barlow-condensed";
  src: url("fonts/library/barlow-condensed/face-0.ttf");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "NTF-barlow-condensed";
  src: url("fonts/library/barlow-condensed/face-1.ttf");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "NTF-barlow-condensed";
  src: url("fonts/library/barlow-condensed/face-2.ttf");
  font-weight: 800;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-1.ttf");
  font-weight: 100 900;
  font-style: italic;
  font-display: swap;
}

/* ---- 核心变量 ---- */
:root {
  /* 基础色彩 */
  --bg: #F4F4F2;
  --bg-subtle: #ECECE9;
  --text: #121314;
  --text-secondary: #585A5E;
  --text-muted: #84878C;
  --border-strong: #121314;
  --border-fine: #D1D2CF;
  --border-muted: #E2E3DF;

  /* 瑞士红及地铁典型色谱（供线路图与对比标记使用） */
  --brand-red: #E63926;
  --brand-red-dark: #C52918;
  --metro-l1-red: #E63926;
  --metro-l2-blue: #0066CC;
  --metro-l3-yellow: #D9822B;
  --metro-l4-green: #00875A;
  --metro-l5-purple: #7038BB;

  /* 状态与交互反馈 */
  --focus: #0066CC;
  --state-active: #121314;
  --state-active-text: #FFFFFF;
  --tag-bg: #E4E5E1;

  /* 排印栈 */
  --font-sans: "NTF-inter", "NTF-noto-sans-sc", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-display: "NTF-barlow-condensed", "NTF-noto-sans-sc", sans-serif;
  --font-mono: "NTF-inter", monospace;

  /* 字阶 (逻辑像素) */
  --fs-display: 80px;
  --fs-h1: 44px;
  --fs-h2: 26px;
  --fs-h3: 20px;
  --fs-lead: 18px;
  --fs-body: 16px;
  --fs-sec: 14px;
  --fs-label: 13px;
  --fs-tick: 12px;

  /* 间距刻度 */
  --space-xs: 6px;
  --space-sm: 12px;
  --space-md: 20px;
  --space-lg: 32px;
  --space-xl: 48px;

  /* 图表用共享数值 */
  --chart-line-thick: 5px;
  --chart-line-medium: 3px;
  --chart-line-fine: 1.5px;
  --chart-node-radius: 7px;
}

/* ---- 画布舞台基础 ---- */
#stage {
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  line-height: 1.5;
  box-sizing: border-box;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* 瑞士网格微结构底纹（精细、克制，辅助对齐感知） */
#stage::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: 
    linear-gradient(to right, rgba(0, 0, 0, 0.035) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(0, 0, 0, 0.035) 1px, transparent 1px);
  background-size: 80px 80px;
  pointer-events: none;
  z-index: 1;
}

/* ---- 变体样式 ---- */
/* 开篇页：特大对比度，色块非对称排布，沉稳而有冲击力 */
html[data-variant="opening"] #stage {
  background-color: var(--bg);
}

/* ---- 共享排印类 ---- */
.nt-display {
  font-family: var(--font-display);
  font-size: var(--fs-display);
  font-weight: 800;
  line-height: 1.0;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  color: var(--text);
  margin: 0;
}

.nt-title {
  font-family: var(--font-display);
  font-size: var(--fs-h1);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.01em;
  color: var(--text);
  margin: 0;
}

.nt-title:lang(zh) {
  font-family: "NTF-noto-sans-sc", sans-serif;
  font-weight: 800;
  letter-spacing: -0.01em;
}

.nt-h2 {
  font-family: var(--font-sans);
  font-size: var(--fs-h2);
  font-weight: 700;
  line-height: 1.25;
  color: var(--text);
  margin: 0;
}

.nt-h3 {
  font-family: var(--font-sans);
  font-size: var(--fs-h3);
  font-weight: 700;
  line-height: 1.3;
  color: var(--text);
  margin: 0;
}

.nt-lead {
  font-size: var(--fs-lead);
  font-weight: 400;
  line-height: 1.5;
  color: var(--text-secondary);
}

.nt-label {
  font-family: var(--font-display);
  font-size: var(--fs-label);
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-secondary);
}

.nt-label:lang(zh) {
  font-family: var(--font-sans);
  font-weight: 700;
  letter-spacing: 0.04em;
}

.nt-tick {
  font-size: var(--fs-tick);
  font-family: var(--font-mono);
  color: var(--text-muted);
}

/* ---- 几何分割线与标尺 ---- */
.nt-divider {
  height: 2px;
  background-color: var(--border-strong);
  border: none;
  margin: var(--space-md) 0;
}

.nt-divider-fine {
  height: 1px;
  background-color: var(--border-fine);
  border: none;
  margin: var(--space-sm) 0;
}

.nt-slash {
  display: inline-block;
  color: var(--brand-red);
  font-weight: 800;
  margin: 0 0.15em;
}

/* ---- 风格化容器与卡片（直角、精密几何） ---- */
.nt-card {
  position: relative;
  background: #FFFFFF;
  border: 1px solid var(--border-fine);
  box-sizing: border-box;
}

.nt-card-strong {
  position: relative;
  background: #FFFFFF;
  border: 2px solid var(--border-strong);
  box-sizing: border-box;
}

.nt-card-header {
  padding: 12px 18px;
  border-bottom: 1px solid var(--border-fine);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--bg-subtle);
}

.nt-card-body {
  padding: 20px;
}

/* 红色高亮信息块（借鉴瑞士标志性红色色块） */
.nt-block-red {
  background-color: var(--brand-red);
  color: #FFFFFF;
  padding: 24px;
  box-sizing: border-box;
}

.nt-block-red .nt-title,
.nt-block-red .nt-display,
.nt-block-red .nt-h2,
.nt-block-red .nt-label {
  color: #FFFFFF;
}

.nt-block-dark {
  background-color: var(--text);
  color: #FFFFFF;
  padding: 24px;
  box-sizing: border-box;
}

.nt-block-dark .nt-title,
.nt-block-dark .nt-h2,
.nt-block-dark .nt-label {
  color: #FFFFFF;
}

/* ---- 线路与换乘专用标记 ---- */
.nt-metro-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 15px;
  height: 26px;
  min-width: 26px;
  padding: 0 8px;
  color: #FFFFFF;
  background-color: var(--border-strong);
  box-sizing: border-box;
  vertical-align: middle;
  line-height: 1;
}

.nt-metro-badge[data-line="1"] { background-color: var(--metro-l1-red); }
.nt-metro-badge[data-line="2"] { background-color: var(--metro-l2-blue); }
.nt-metro-badge[data-line="3"] { background-color: var(--metro-l3-yellow); }
.nt-metro-badge[data-line="4"] { background-color: var(--metro-l4-green); }

.nt-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: var(--fs-label);
  font-weight: 600;
  padding: 4px 10px;
  background: var(--tag-bg);
  border: 1px solid var(--border-fine);
  color: var(--text);
  line-height: 1.2;
}

.nt-tag-accent {
  background: #FFF0ED;
  border-color: #FFAAA0;
  color: var(--brand-red-dark);
}

/* ---- 交互控件体系 ---- */
.nt-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  font-weight: 600;
  padding: 10px 22px;
  background: #FFFFFF;
  color: var(--text);
  border: 2px solid var(--border-strong);
  cursor: pointer;
  box-sizing: border-box;
  text-decoration: none;
  border-radius: 0;
  transition: background-color 0.15s ease, color 0.15s ease;
}

.nt-btn:hover {
  background: var(--text);
  color: #FFFFFF;
}

.nt-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.nt-btn[aria-pressed="true"],
.nt-btn.is-active {
  background: var(--text);
  color: #FFFFFF;
}

.nt-btn-primary {
  background: var(--brand-red);
  color: #FFFFFF;
  border-color: var(--brand-red);
}

.nt-btn-primary:hover {
  background: var(--brand-red-dark);
  border-color: var(--brand-red-dark);
  color: #FFFFFF;
}

.nt-btn-primary[aria-pressed="true"],
.nt-btn-primary.is-active {
  background: #961A0C;
  border-color: #961A0C;
  color: #FFFFFF;
}

.nt-segmented-group {
  display: inline-flex;
  border: 2px solid var(--border-strong);
  background: #FFFFFF;
}

.nt-segmented-btn {
  border: none;
  background: transparent;
  padding: 10px 20px;
  font-family: var(--font-sans);
  font-size: var(--fs-sec);
  font-weight: 700;
  color: var(--text);
  cursor: pointer;
  transition: all 0.12s ease;
  border-right: 1px solid var(--border-fine);
}

.nt-segmented-btn:last-child {
  border-right: none;
}

.nt-segmented-btn:hover {
  background: var(--bg-subtle);
}

.nt-segmented-btn[aria-pressed="true"],
.nt-segmented-btn.is-selected {
  background: var(--text);
  color: #FFFFFF;
}

/* ---- 路线网络与数据对比专用图表样式 ---- */
svg.nt-metro-network {
  display: block;
  overflow: visible;
}

/* 路线路径基础 */
.nt-track-line {
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.nt-track-l1 { stroke: var(--metro-l1-red); stroke-width: var(--chart-line-thick); }
.nt-track-l2 { stroke: var(--metro-l2-blue); stroke-width: var(--chart-line-thick); }
.nt-track-l3 { stroke: var(--metro-l3-yellow); stroke-width: var(--chart-line-thick); }

/* 站点与换乘枢纽 */
.nt-station-node {
  fill: #FFFFFF;
  stroke: var(--border-strong);
  stroke-width: 2.5px;
  cursor: pointer;
  transition: transform 0.12s ease;
}

.nt-station-node:hover {
  transform: scale(1.2);
}

.nt-station-transfer {
  fill: #FFFFFF;
  stroke: var(--border-strong);
  stroke-width: 3.5px;
}

.nt-station-label {
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: 700;
  fill: var(--text);
  text-anchor: middle;
  dominant-baseline: middle;
  pointer-events: none;
}

/* 时间条柱状对比图 */
.nt-time-bar-wrapper {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.nt-time-segment {
  display: flex;
  height: 38px;
  width: 100%;
  background: var(--bg-subtle);
  border: 1px solid var(--border-fine);
  overflow: hidden;
}

.nt-segment-ride {
  background: #0066CC;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #FFFFFF;
  font-size: 13px;
  font-weight: 700;
  font-family: var(--font-mono);
}

.nt-segment-wait {
  background: #D9822B;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #FFFFFF;
  font-size: 13px;
  font-weight: 700;
  font-family: var(--font-mono);
}

.nt-segment-transfer {
  background: #E63926;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #FFFFFF;
  font-size: 13px;
  font-weight: 700;
  font-family: var(--font-mono);
}

/* 提示与批注标识 */
.nt-callout {
  border-left: 4px solid var(--border-strong);
  background: #FFFFFF;
  padding: 14px 18px;
}

.nt-callout-red {
  border-left-color: var(--brand-red);
  background: #FFF5F4;
}

/* 辅助重置与无障碍保障 */
@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
    animation: none !important;
  }
}
